diff --git a/source/common/json/wuffs_json/parser_config.cc b/source/common/json/wuffs_json/parser_config.cc
--- a/source/common/json/wuffs_json/parser_config.cc
+++ b/source/common/json/wuffs_json/parser_config.cc
@@ -0,0 +1,195 @@
+#include "source/common/json/wuffs_json/parser_config.h"
+
+#include <string>
+#include <utility>
+#include <vector>
+
+#include "absl/status/status.h"
+#include "absl/status/statusor.h"
+#include "absl/strings/str_cat.h"
+
+namespace Envoy {
+namespace Json {
+namespace Wuffs {
+namespace {
+
+using Segment = WuffsJsonCursor::PatternSegment;
+
+// Rejects structural problems detectable before character-by-character parsing.
+absl::Status validatePathSyntax(absl::string_view path) {
+  if (path.empty()) {
+    return absl::InvalidArgumentError("extract_field_spec: path must not be empty");
+  }
+  if (path.front() == '.') {
+    return absl::InvalidArgumentError("extract_field_spec: path must not start with '.'");
+  }
+  if (path.back() == '.') {
+    return absl::InvalidArgumentError("extract_field_spec: path must not end with '.'");
+  }
+  // '\' is reserved for a future escape syntax for document keys containing
+  // '.', '[', ']' Rejecting it now keeps that extension non-breaking.
+  if (path.find('\\') != absl::string_view::npos) {
+    return absl::InvalidArgumentError(
+        "extract_field_spec: '\\' is reserved for future escape syntax");
+  }
+  return absl::OkStatus();
+}
+
+absl::Status appendSegment(std::vector<Segment>& segments, Segment segment, int max_depth) {
+  if (max_depth > 0 && segments.size() >= static_cast<size_t>(max_depth)) {
+    return absl::InvalidArgumentError(absl::StrCat("extract_field_spec: path depth ",
+                                                   segments.size() + 1,
+                                                   " exceeds maximum supported depth ", max_depth));
+  }
+  segments.push_back(std::move(segment));
+  return absl::OkStatus();
+}
+
+class ExtractFieldSpecParser {
+public:
+  explicit ExtractFieldSpecParser(int max_depth) : max_depth_(max_depth) {}
+
+  // `path` is borrowed for the duration of this call only — never retained past
+  // the return, so the caller's buffer does not have to outlive the parser.
+  absl::StatusOr<std::vector<Segment>> parse(absl::string_view path) {
+    path_ = path;
+    std::vector<Segment> segments;
+    for (size_t i = 0; i < path_.size(); ++i) {
+      if (auto status = consume(i, segments); !status.ok()) {
+        return status;
+      }
+    }
+    if (in_array_) {
+      return absl::InvalidArgumentError("extract_field_spec: unterminated '[' in path");
+    }
+    if (auto status = flushKey(path_.size(), segments); !status.ok()) {
+      return status;
+    }
+    if (segments.empty()) {
+      return absl::InvalidArgumentError("extract_field_spec: path contains no segments");
+    }
+    return segments;
+  }
+
+private:
+  absl::Status consume(size_t i, std::vector<Segment>& segments) {
+    switch (path_[i]) {
+    case '[':
+      return openArray(i, segments);
+    case ']':
+      return closeArray(segments);
+    case '.':
+      return separator(i, segments);
+    default:
+      return keyCharacter(i);
+    }
+  }
+
+  absl::Status openArray(size_t i, std::vector<Segment>& segments) {
+    if (in_array_) {
+      return absl::InvalidArgumentError("extract_field_spec: nested '[' in path");
+    }
+    // '.' immediately before '[' is invalid: the canonical pattern-path
+    // syntax never contains '.[]' — '[]' always directly follows the parent dict key.
+    if (i > 0 && path_[i - 1] == '.') {
+      return absl::InvalidArgumentError(
+          "extract_field_spec: '.' before '[' is not valid; use 'key[]' not 'key.[]'");
+    }
+    if (auto status = flushKey(i, segments); !status.ok()) {
+      return status;
+    }
+    in_array_ = true;
+    return absl::OkStatus();
+  }
+
+  absl::Status closeArray(std::vector<Segment>& segments) {
+    if (!in_array_) {
+      return absl::InvalidArgumentError("extract_field_spec: unexpected ']' in path");
+    }
+    if (auto status = appendSegment(segments, Segment{"", /*is_array_element=*/true}, max_depth_);
+        !status.ok()) {
+      return status;
+    }
+    in_array_ = false;
+    return absl::OkStatus();
+  }
+
+  absl::Status separator(size_t i, std::vector<Segment>& segments) {
+    if (in_array_) {
+      return absl::InvalidArgumentError("extract_field_spec: '.' inside '[]' in path");
+    }
+    if (!has_key_ && i > 0 && path_[i - 1] == '.') {
+      return absl::InvalidArgumentError(
+          absl::StrCat("extract_field_spec: consecutive '.' at position ", i, " in path"));
+    }
+    return flushKey(i, segments);
+  }
+
+  absl::Status keyCharacter(size_t i) {
+    if (in_array_) {
+      // Index-based addressing (e.g. "[42]") is intentionally unsupported.
+      // Path specs are structural patterns: '[]' means "every element" because
+      // LLM/MCP arrays (messages[], choices[], result.content[]) are homogeneous
+      // lists where every element is processed.
+      // We can implement index-based addressing if needed in the future.
+      return absl::InvalidArgumentError(
+          "extract_field_spec: only '[]' wildcard is supported, not '[...]'");
+    }
+    // A key may not start directly after ']': the canonical pattern-path
+    // syntax always has a '.' separator between an array wildcard and a
+    // following dict key ("a[].b", never "a[]b").
+    if (i > 0 && path_[i - 1] == ']') {
+      return absl::InvalidArgumentError("extract_field_spec: missing '.' between ']' and key");
+    }
+    if (!has_key_) {
+      segment_start_ = i;
+      has_key_ = true;
+    }
+    return absl::OkStatus();
+  }
+
+  absl::Status flushKey(size_t end, std::vector<Segment>& segments) {
+    if (!has_key_) {
+      return absl::OkStatus();
+    }
+    has_key_ = false;
+    return appendSegment(segments,
+                         Segment{std::string(path_.substr(segment_start_, end - segment_start_)),
+                                 /*is_array_element=*/false},
+                         max_depth_);
+  }
+
+  const int max_depth_;
+  // Set at entry to parse() and valid only for that call; see the note there.
+  absl::string_view path_;
+  bool in_array_{false};
+  bool has_key_{false};
+  size_t segment_start_{0};
+};
+
+} // namespace
+
+absl::StatusOr<ExtractFieldSpec> parseExtractFieldSpec(absl::string_view path, int max_depth) {
+  if (absl::Status status = validatePathSyntax(path); !status.ok()) {
+    return status;
+  }
+  absl::StatusOr<std::vector<Segment>> segments = ExtractFieldSpecParser(max_depth).parse(path);
+  if (!segments.ok()) {
+    return segments.status();
+  }
+  ExtractFieldSpec out;
+  out.segments = *std::move(segments);
+  return out;
+}
+
+absl::Status ParserConfig::validate() const {
+  if (capture_all_scalars && !extract_fields.empty()) {
+    return absl::InvalidArgumentError("parser_config: capture_all_scalars and extract_fields are "
+                                      "mutually exclusive; set at most one extraction mode");
+  }
+  return absl::OkStatus();
+}
+
+} // namespace Wuffs
+} // namespace Json
+} // namespace Envoy

diff --git a/source/common/json/wuffs_json/parser_config.h b/source/common/json/wuffs_json/parser_config.h
--- a/source/common/json/wuffs_json/parser_config.h
+++ b/source/common/json/wuffs_json/parser_config.h
@@ -0,0 +1,113 @@
+#pragma once
+
+#include <cstddef>
+#include <vector>
+
+#include "source/common/json/wuffs_json/wuffs_json_cursor.h"
+
+#include "absl/status/status.h"
+#include "absl/status/statusor.h"
+#include "absl/strings/string_view.h"
+
+namespace Envoy {
+namespace Json {
+namespace Wuffs {
+
+// Parsed representation of the JSON field path used for customized target extraction.
+// TODO(tyxia) Add per-field capture.
+struct ExtractFieldSpec {
+  // Each segment is a dict key or an [] wildcard. Pass straight to
+  // WuffsJsonCursor::matchesPatternPath — no conversion needed.
+  std::vector<WuffsJsonCursor::PatternSegment> segments;
+};
+
+// Parse and convert the path string into a valid and structured ExtractFieldSpec.
+// Returns InvalidArgumentError on empty/malformed input).
+//
+// How to write a path:
+//   Navigate through your JSON until you reach the value to extract:
+//     - If the current level is a JSON object: write the field name (e.g. "params")
+//     - If the current level is a JSON array: write the field name followed by '[]'
+//       (e.g. "messages[]") — this applies the rest of the path to each element
+//     - Separate levels with '.'
+//
+// Syntax constraints:
+//   - Field names are non-empty and cannot contain '.', '[', ']', or '\'.
+//   - '[]' must immediately follow a field name or another '[]', never a '.'.
+//   - A field name after '[]' must be preceded by '.'.
+//   - '\' is reserved for a future escape syntax and is rejected.
+//
+// Example (segments below are shown by key; a wildcard is {"", is_array=true}):
+//   parseExtractFieldSpec("messages[].role")
+//     → segments = {"messages",  // dict key
+//                   [],          // [] wildcard
+//                   "role"},     // dict key
+//                                // depth 3
+//
+//   parseExtractFieldSpec("model")                   // top-level scalar
+//     → segments = {"model"}                         // depth 1
+//
+//   parseExtractFieldSpec("params._meta.traceparent") // nested dict scalar
+//     → segments = {"params", "_meta", "traceparent"} // depth 3
+//
+//   parseExtractFieldSpec("params.protocolVersion")  // MCP initialize
+//     → segments = {"params", "protocolVersion"}     // depth 2
+//
+//   parseExtractFieldSpec("params.message.taskId")   // A2A task correlation
+//     → segments = {"params", "message", "taskId"}   // depth 3
+//
+//   parseExtractFieldSpec("usage.total_tokens")      // OpenAI response usage
+//     → segments = {"usage", "total_tokens"}         // depth 2
+//
+//   parseExtractFieldSpec("tools[].function.name")   // scalar in a dict inside
+//     → segments = {"tools",     // each array element
+//                   [],
+//                   "function",
+//                   "name"}      // depth 4
+//
+// Note: keys containing '.', '[]', or "" cannot be addressed — '.' always
+// splits segments, so "vendor.example.com/token" parses as three segments
+// and matches nothing at runtime. Address this in the future if needed.
+absl::StatusOr<ExtractFieldSpec> parseExtractFieldSpec(absl::string_view path, int max_depth = 0);
+
+// Configuration that controls the JSON parser. Populated at filter init.
+struct ParserConfig {
+  // Maximum raw body bytes to feed to cursor (0 = no limit).
+  size_t max_body_bytes{0};
+
+  // Maximum decoded bytes for a single scalar string value. Over-budget values
+  // are dropped entirely (never truncated); parsing continues past them.
+  // 0 = no per-value limit.
+  size_t max_per_scalar_bytes{0};
+
+  // Maximum total captured bytes across all scalar values in one body. A value
+  // that would push the running total over the budget is dropped; a later
+  // smaller value that still fits is captured. 0 = no total limit.
+  size_t max_total_scalar_bytes{0};
+
+  // When true, capture every scalar value (strings, numbers, booleans, nulls)
+  // at any depth. The cursor rejects nesting deeper than kMaxTrackedDepth - 1,
+  // so that is the effective ceiling.
+  //
+  // Mutually exclusive with extract_fields; validate() rejects parser config that
+  // sets both.
+  //
+  // TODO(tyxia): (1) configurable max capture depth; (2) inside-array scope
+  // cutoff; (3) qualified naming for nested scalars.
+  bool capture_all_scalars{false};
+
+  // Operator-declared JSON fields to extract from the body. Mutually exclusive
+  // with capture_all_scalars.
+  //
+  // The handler passes a spec's segments straight to
+  // cursor.matchesPatternPath(segments, depth) at each scalar callback.
+  std::vector<ExtractFieldSpec> extract_fields;
+
+  // Returns InvalidArgumentError if capture_all_scalars and extract_fields are
+  // both set.
+  absl::Status validate() const;
+};
+
+} // namespace Wuffs
+} // namespace Json
+} // namespace Envoy

