+ */
+typedef void* envoy_dynamic_module_type_matcher_data_input_envoy_ptr;
+
+// =============================================================================
+// Matcher Data Input Event Hooks
+// =============================================================================
+
+/**
+ * envoy_dynamic_module_on_matcher_data_input_config_new is called when a new matcher data input
