diff --git a/source/extensions/dynamic_modules/sdk/rust/src/lib_test.rs b/source/extensions/dynamic_modules/sdk/rust/src/lib_test.rs
--- a/source/extensions/dynamic_modules/sdk/rust/src/lib_test.rs
+++ b/source/extensions/dynamic_modules/sdk/rust/src/lib_test.rs
@@ -7199,6 +7199,188 @@ fn test_matcher_get_all_headers() {
     .is_none());
 }

+// =============================================================================
+// Matcher Data Input FFI stubs and tests.
+// =============================================================================
+
+// Controls whether the data input header lookup stub reports the header as present.
+static STUB_DATA_INPUT_HEADER_PRESENT: AtomicBool = AtomicBool::new(true);
+// Canned request header value returned by the data input header lookup stub.
+const STUB_DATA_INPUT_HEADER_VALUE: &[u8] = b"cluster_0";
+
+#[no_mangle]
+pub extern "C" fn envoy_dynamic_module_callback_matcher_data_input_get_header_value(
+  _data_input_envoy_ptr: abi::envoy_dynamic_module_type_matcher_data_input_envoy_ptr,
+  _header_type: abi::envoy_dynamic_module_type_http_header_type,
+  _key: abi::envoy_dynamic_module_type_module_buffer,
+  result: *mut abi::envoy_dynamic_module_type_envoy_buffer,
+  _index: usize,
+  total_count_out: *mut usize,
+) -> bool {
+  if !STUB_DATA_INPUT_HEADER_PRESENT.load(std::sync::atomic::Ordering::SeqCst) {
+    if !total_count_out.is_null() {
+      unsafe { *total_count_out = 0 };
+    }
+    return false;
+  }
+  if !total_count_out.is_null() {
+    unsafe { *total_count_out = 1 };
+  }
+  unsafe {
+    *result = abi::envoy_dynamic_module_type_envoy_buffer {
+      ptr: STUB_DATA_INPUT_HEADER_VALUE.as_ptr() as *mut _,
+      length: STUB_DATA_INPUT_HEADER_VALUE.len(),
+    };
+  }
+  true
+}
+
+// Captures the value the module hands back through set_result so tests can assert on it.
+static CAPTURED_DATA_INPUT_RESULT: std::sync::Mutex<Vec<u8>> = std::sync::Mutex::new(Vec::new());
+static DATA_INPUT_RESULT_SET: AtomicBool = AtomicBool::new(false);
+
+#[no_mangle]
+pub extern "C" fn envoy_dynamic_module_callback_matcher_data_input_set_result(
+  _data_input_envoy_ptr: abi::envoy_dynamic_module_type_matcher_data_input_envoy_ptr,
+  result: abi::envoy_dynamic_module_type_module_buffer,
+) {
+  let bytes =
+    unsafe { crate::ffi_helpers::slice_from_raw_or_empty(result.ptr as *const u8, result.length) };
+  *CAPTURED_DATA_INPUT_RESULT.lock().unwrap() = bytes.to_vec();
+  DATA_INPUT_RESULT_SET.store(true, std::sync::atomic::Ordering::SeqCst);
+}
+
+// Test data input that echoes the request header named by its config bytes.
+struct TestStringDataInput {
+  header: String,
+}
+
+impl crate::matcher_data_input::MatcherDataInput for TestStringDataInput {
+  fn new(_name: &str, config: &[u8]) -> Result<Self, String> {
+    if config.is_empty() {
+      return Err("a header name is required".to_string());
+    }
+    Ok(Self {
+      header: String::from_utf8_lossy(config).to_string(),
+    })
+  }
+
+  fn get(&self, ctx: &crate::matcher_data_input::DataInputContext) -> Option<Vec<u8>> {
+    // The sentinel header name drives the fail-closed panic path in a test.
+    if self.header == "panic" {
+      panic!("test panic in data input get");
+    }
+    ctx.get_request_header(&self.header).map(<[u8]>::to_vec)
+  }
+}
+
+declare_matcher_data_input!(TestStringDataInput);
+
+#[test]
+fn test_matcher_data_input_context_reads_header() {
+  let ctx = crate::matcher_data_input::DataInputContext::new(std::ptr::null_mut());
+
+  STUB_DATA_INPUT_HEADER_PRESENT.store(true, std::sync::atomic::Ordering::SeqCst);
+  assert_eq!(
+    ctx.get_request_header("x-route"),
+    Some(STUB_DATA_INPUT_HEADER_VALUE)
+  );
+
+  // Response header and response trailer lookups reach the same callback.
+  assert_eq!(
+    ctx.get_response_header("x-route"),
+    Some(STUB_DATA_INPUT_HEADER_VALUE)
+  );
+  assert_eq!(
+    ctx.get_response_trailer("x-route"),
+    Some(STUB_DATA_INPUT_HEADER_VALUE)
+  );
+
+  // An absent header is reported as None.
+  STUB_DATA_INPUT_HEADER_PRESENT.store(false, std::sync::atomic::Ordering::SeqCst);
+  assert_eq!(ctx.get_request_header("x-route"), None);
+}
+
+#[test]
+fn test_matcher_data_input_hooks() {
+  let name = b"test";
+  let name_buf = abi::envoy_dynamic_module_type_envoy_buffer {
+    ptr: name.as_ptr() as *mut _,
+    length: name.len(),
+  };
+
+  // config_new rejects an empty config by returning null.
+  let empty_config = abi::envoy_dynamic_module_type_envoy_buffer {
+    ptr: std::ptr::null_mut(),
+    length: 0,
+  };
+  let null_config = envoy_dynamic_module_on_matcher_data_input_config_new(
+    std::ptr::null_mut(),
+    name_buf,
+    empty_config,
+  );
+  assert!(null_config.is_null());
+
+  // config_new succeeds when a header name is provided.
+  let header_name = b"x-route";
+  let config_buf = abi::envoy_dynamic_module_type_envoy_buffer {
+    ptr: header_name.as_ptr() as *mut _,
+    length: header_name.len(),
+  };
+  let config_ptr = envoy_dynamic_module_on_matcher_data_input_config_new(
+    std::ptr::null_mut(),
+    name_buf,
+    config_buf,
+  );
+  assert!(!config_ptr.is_null());
+
+  // A present header is handed back through set_result.
+  STUB_DATA_INPUT_HEADER_PRESENT.store(true, std::sync::atomic::Ordering::SeqCst);
+  DATA_INPUT_RESULT_SET.store(false, std::sync::atomic::Ordering::SeqCst);
+  envoy_dynamic_module_on_matcher_data_input_get(config_ptr, std::ptr::null_mut());
+  assert!(DATA_INPUT_RESULT_SET.load(std::sync::atomic::Ordering::SeqCst));
+  assert_eq!(
+    *CAPTURED_DATA_INPUT_RESULT.lock().unwrap(),
+    STUB_DATA_INPUT_HEADER_VALUE
+  );
+
+  // An absent header leaves the result unset, so the input has no value.
+  STUB_DATA_INPUT_HEADER_PRESENT.store(false, std::sync::atomic::Ordering::SeqCst);
+  DATA_INPUT_RESULT_SET.store(false, std::sync::atomic::Ordering::SeqCst);
+  envoy_dynamic_module_on_matcher_data_input_get(config_ptr, std::ptr::null_mut());
+  assert!(!DATA_INPUT_RESULT_SET.load(std::sync::atomic::Ordering::SeqCst));
+
+  envoy_dynamic_module_on_matcher_data_input_config_destroy(config_ptr);
+}
+
+#[test]
+fn test_matcher_data_input_get_recovers_from_panic() {
+  let name = b"test";
+  let name_buf = abi::envoy_dynamic_module_type_envoy_buffer {
+    ptr: name.as_ptr() as *mut _,
+    length: name.len(),
+  };
+  // The config selects the header name "panic", which makes the test get() panic.
+  let panic_header = b"panic";
+  let config_buf = abi::envoy_dynamic_module_type_envoy_buffer {
+    ptr: panic_header.as_ptr() as *mut _,
+    length: panic_header.len(),
+  };
+  let config_ptr = envoy_dynamic_module_on_matcher_data_input_config_new(
+    std::ptr::null_mut(),
+    name_buf,
+    config_buf,
+  );
+  assert!(!config_ptr.is_null());
+
+  // A panic in get() is caught and no result is set, so the input has no value.
+  DATA_INPUT_RESULT_SET.store(false, std::sync::atomic::Ordering::SeqCst);
+  envoy_dynamic_module_on_matcher_data_input_get(config_ptr, std::ptr::null_mut());
+  assert!(!DATA_INPUT_RESULT_SET.load(std::sync::atomic::Ordering::SeqCst));
+
+  envoy_dynamic_module_on_matcher_data_input_config_destroy(config_ptr);
+}
+
 // =============================================================================
 // Stats Sink unit tests
 // =============================================================================

diff --git a/source/extensions/dynamic_modules/sdk/rust/src/matcher_data_input.rs b/source/extensions/dynamic_modules/sdk/rust/src/matcher_data_input.rs
--- a/source/extensions/dynamic_modules/sdk/rust/src/matcher_data_input.rs
+++ b/source/extensions/dynamic_modules/sdk/rust/src/matcher_data_input.rs
@@ -0,0 +1,231 @@
+//! Matcher string data input support for dynamic modules.
+//!
+//! This module provides traits and types for implementing a matcher data input as a dynamic module.
+//! The module extracts a value from the HTTP request and response during match evaluation, and
+//! downstream map matchers dispatch on that value. This lets a module select one of many matches
+//! with a single evaluation and without clearing the route cache.
+
+use crate::abi;
+use std::ffi::c_void;
+use std::ptr;
+
+/// Read-only context for accessing HTTP matching data during a data input get evaluation.
+///
+/// This is passed to [`MatcherDataInput::get`] to provide access to HTTP headers. The context is
+/// only valid during the get callback and must not be stored.
+pub struct DataInputContext {
+  envoy_ptr: *mut c_void,
+}
+
+impl DataInputContext {
+  /// Create a new DataInputContext. Used internally by the macro.
+  #[doc(hidden)]
+  pub fn new(envoy_ptr: *mut c_void) -> Self {
+    Self { envoy_ptr }
+  }
+
+  /// Get a request header value by key.
+  ///
+  /// Returns the header value as bytes, or `None` if the header is not present.
+  pub fn get_request_header(&self, key: &str) -> Option<&[u8]> {
+    self.get_header_value(
+      abi::envoy_dynamic_module_type_http_header_type::RequestHeader,
+      key,
+    )
+  }
+
+  /// Get a response header value by key.
+  ///
+  /// Returns the header value as bytes, or `None` if the header is not present.
+  pub fn get_response_header(&self, key: &str) -> Option<&[u8]> {
+    self.get_header_value(
+      abi::envoy_dynamic_module_type_http_header_type::ResponseHeader,
+      key,
+    )
+  }
+
+  /// Get a response trailer value by key.
+  ///
+  /// Returns the trailer value as bytes, or `None` if the trailer is not present.
+  pub fn get_response_trailer(&self, key: &str) -> Option<&[u8]> {
+    self.get_header_value(
+      abi::envoy_dynamic_module_type_http_header_type::ResponseTrailer,
+      key,
+    )
+  }
+
+  /// Get a header value by type and key.
+  fn get_header_value(
+    &self,
+    header_type: abi::envoy_dynamic_module_type_http_header_type,
+    key: &str,
+  ) -> Option<&[u8]> {
+    let key_buf = abi::envoy_dynamic_module_type_module_buffer {
+      ptr: key.as_ptr() as *const _,
+      length: key.len(),
+    };
+    let mut result = abi::envoy_dynamic_module_type_envoy_buffer {
+      ptr: ptr::null_mut(),
+      length: 0,
+    };
+    if unsafe {
+      abi::envoy_dynamic_module_callback_matcher_data_input_get_header_value(
+        self.envoy_ptr,
+        header_type,
+        key_buf,
+        &mut result,
+        0,
+        ptr::null_mut(),
+      )
+    } {
+      unsafe {
+        Some(crate::ffi_helpers::slice_from_raw_or_empty(
+          result.ptr as *const u8,
+          result.length,
+        ))
+      }
+    } else {
+      None
+    }
+  }
+
+  /// Provide the value extracted for this evaluation. Used internally by the macro.
+  #[doc(hidden)]
+  pub fn set_result(&self, value: &[u8]) {
+    let buffer = abi::envoy_dynamic_module_type_module_buffer {
+      ptr: value.as_ptr() as *const _,
+      length: value.len(),
+    };
+    unsafe {
+      abi::envoy_dynamic_module_callback_matcher_data_input_set_result(self.envoy_ptr, buffer);
+    }
+  }
+}
+
+/// Trait that the dynamic module must implement to provide a matcher data input.
+///
+/// The implementation is created once during configuration loading and shared across all get
+/// evaluations. It must be `Send + Sync` since evaluation can happen on any worker thread.
+pub trait MatcherDataInput: Sized + Send + Sync + 'static {
+  /// Create a new data input configuration from the provided name and config bytes.
+  ///
+  /// # Arguments
+  /// * `name` - The data input configuration name from the proto config.
+  /// * `config` - The raw configuration bytes from the proto config.
+  ///
+  /// # Returns
+  /// The data input configuration on success, or an error string on failure.
+  fn new(name: &str, config: &[u8]) -> Result<Self, String>;
+
+  /// Extract the value used for matching.
+  ///
+  /// This is called on worker threads during match evaluation. The `ctx` provides access to HTTP
+  /// headers. Returning `None` means the input has no value, which downstream map matchers treat as
+  /// no match.
+  fn get(&self, ctx: &DataInputContext) -> Option<Vec<u8>>;
+}
+
+/// Macro to declare matcher data input entry points.
+///
+/// This macro generates the required C ABI functions that Envoy calls to interact with the data
+/// input implementation.
+///
+/// # Example
+///
+/// ```
+/// use envoy_proxy_dynamic_modules_rust_sdk::declare_matcher_data_input;
+/// use envoy_proxy_dynamic_modules_rust_sdk::matcher_data_input::*;
+///
+/// struct MyDataInput {
+///   header: String,
+/// }
+///
+/// impl MatcherDataInput for MyDataInput {
+///   fn new(_name: &str, config: &[u8]) -> Result<Self, String> {
+///     Ok(Self {
+///       header: String::from_utf8_lossy(config).to_string(),
+///     })
+///   }
+///
+///   fn get(&self, ctx: &DataInputContext) -> Option<Vec<u8>> {
+///     ctx.get_request_header(&self.header).map(|v| v.to_vec())
+///   }
+/// }
+///
+/// declare_matcher_data_input!(MyDataInput);
+/// ```
+#[macro_export]
+macro_rules! declare_matcher_data_input {
+  ($config_type:ty) => {
+    #[no_mangle]
+    pub extern "C" fn envoy_dynamic_module_on_matcher_data_input_config_new(
+      _config_envoy_ptr: *mut ::std::ffi::c_void,
+      name: $crate::abi::envoy_dynamic_module_type_envoy_buffer,
+      config: $crate::abi::envoy_dynamic_module_type_envoy_buffer,
+    ) -> *const ::std::ffi::c_void {
+      ::std::panic::catch_unwind(::std::panic::AssertUnwindSafe(|| {
+        // Safe under `(nullptr, 0)` via `ffi_helpers`. The data input name is used as a registry
+        // lookup key by user `MatcherDataInput::new` implementations, so invalid UTF-8 must map to
+        // the empty string rather than being rewritten with `U+FFFD` substitutions. The latter
+        // would silently route invalid bytes to a different registry entry.
+        let name_slice = unsafe {
+          $crate::ffi_helpers::slice_from_raw_or_empty(name.ptr as *const u8, name.length)
+        };
+        let name_str: &str = ::std::str::from_utf8(name_slice).unwrap_or("");
+        let config_bytes = unsafe {
+          $crate::ffi_helpers::slice_from_raw_or_empty(config.ptr as *const u8, config.length)
+        };
+
+        match <$config_type as $crate::matcher_data_input::MatcherDataInput>::new(
+          name_str,
+          config_bytes,
+        ) {
+          Ok(c) => Box::into_raw(Box::new(c)) as *const ::std::ffi::c_void,
+          Err(_) => ::std::ptr::null(),
+        }
+      }))
+      .unwrap_or_else(|panic| {
+        $crate::log_ffi_panic(
+          "envoy_dynamic_module_on_matcher_data_input_config_new",
+          panic,
+        );
+        ::std::ptr::null()
+      })
+    }
+
+    #[no_mangle]
+    pub extern "C" fn envoy_dynamic_module_on_matcher_data_input_config_destroy(
+      config_ptr: *const ::std::ffi::c_void,
+    ) {
+      let _ = ::std::panic::catch_unwind(::std::panic::AssertUnwindSafe(|| unsafe {
+        drop(Box::from_raw(config_ptr as *mut $config_type));
+      }))
+      .map_err(|panic| {
+        $crate::log_ffi_panic(
+          "envoy_dynamic_module_on_matcher_data_input_config_destroy",
+          panic,
+        );
+      });
+    }
+
+    #[no_mangle]
+    pub extern "C" fn envoy_dynamic_module_on_matcher_data_input_get(
+      config_ptr: *const ::std::ffi::c_void,
+      data_input_envoy_ptr: *mut ::std::ffi::c_void,
+    ) {
+      let _ = ::std::panic::catch_unwind(::std::panic::AssertUnwindSafe(|| {
+        let config = unsafe { &*(config_ptr as *const $config_type) };
+        let ctx = $crate::matcher_data_input::DataInputContext::new(data_input_envoy_ptr);
+        // A panic or a `None` result leaves the value unset, so the input has no value.
+        if let Some(value) =
+          <$config_type as $crate::matcher_data_input::MatcherDataInput>::get(config, &ctx)
+        {
+          ctx.set_result(&value);
+        }
+      }))
+      .map_err(|panic| {
+        $crate::log_ffi_panic("envoy_dynamic_module_on_matcher_data_input_get", panic);
+      });
+    }
+  };
+}

