+WasmConfig::WasmConfig(const envoy::extensions::wasm::v3::PluginConfig& config)
+    : config_(normalizeConfig(config)) {
+  for (auto& capability :
+       config_.vm_config().capability_restriction_config().allowed_capabilities()) {
